class Solution { public String alienOrder(String[] w) { boolean[] seen=new boolean[26];int count=0;for(String s:w)for(char c:s.toCharArray())if(!seen[c-'a']){seen[c-'a']=true;count++;}List<Set<Integer>>g=new ArrayList<>();for(int i=0;i<26;i++)g.add(new HashSet<>());int[]d=new int[26];for(int k=1;k<w.length;k++){String a=w[k-1],b=w[k];int i=0;while(i<a.length()&&i<b.length()&&a.charAt(i)==b.charAt(i))i++;if(i==b.length()&&a.length()>b.length())return "";if(i<a.length()&&i<b.length()){int x=a.charAt(i)-'a',y=b.charAt(i)-'a';if(g.get(x).add(y))d[y]++;}}PriorityQueue<Integer>q=new PriorityQueue<>();for(int i=0;i<26;i++)if(seen[i]&&d[i]==0)q.add(i);StringBuilder out=new StringBuilder();while(!q.isEmpty()){int u=q.remove();out.append((char)(u+'a'));for(int v:g.get(u))if(--d[v]==0)q.add(v);}return out.length()==count?out.toString():"";} }
